Language: C

#include <stdio.h>

/* Returns the index of key in the sorted array a[0..n-1], or -1. */
int binarySearch(const int a[], int n, int key) {
    int low = 0, high = n - 1;
    while (low <= high) {
        int mid = low + (high - low) / 2;   /* avoids overflow of low + high */
        if (a[mid] == key)
            return mid;
        else if (a[mid] < key)
            low = mid + 1;                  /* search right half */
        else
            high = mid - 1;                 /* search left half */
    }
    return -1;
}

int main(void) {
    int a[] = {3, 8, 15, 23, 42, 57, 91};
    int n = sizeof(a) / sizeof(a[0]);
    printf("%d\n", binarySearch(a, n, 42));   /* prints 4 */
    printf("%d\n", binarySearch(a, n, 10));   /* prints -1 */
    return 0;
}

Complexity: worst and average case O(log n), best case O(1); extra space O(1).

