class TreeNode:
    def __init__(self, val):
        self.val = val
        self.left = None
        self.right = None

def insert(root, val):
    """Insert a value into BST. Returns the (possibly new) root."""
    if root is None:
        return TreeNode(val)   # create new node
    if val < root.val:
        root.left = insert(root.left, val)   # go left
    elif val > root.val:
        root.right = insert(root.right, val) # go right
    # if val == root.val: ignore duplicates (standard BST)
    return root

def search(root, target):
    """Search for target in BST. Returns True if found, False otherwise."""
    if root is None:
        return False
    if target == root.val:
        return True
    elif target < root.val:
        return search(root.left, target)
    else:
        return search(root.right, target)

def inorder(root, result=[]):
    if root:
        inorder(root.left, result)
        result.append(root.val)
        inorder(root.right, result)
    return result

