    """BST-এ একটি value insert করুন। (সম্ভাব্য নতুন) root return করুন।"""
    if root is None:
        return TreeNode(val)   # নতুন node তৈরি করুন
    if val < root.val:
        root.left = insert(root.left, val)   # left-এ যান
    elif val > root.val:
        root.right = insert(root.right, val) # right-এ যান
    # val == root.val হলে: duplicates ignore করুন (standard BST)
    return root

def search(root, target):
    """BST-এ target search করুন। পাওয়া গেলে True, না হলে False return করুন।"""
    if root is None:
        return False
    if target == root.val:
        return True
    elif target < root.val:
        return search(root.left, target)
    else:
        return search(root.right, target)

def inorder(root, result=[]):
    if root:
        inorder(root.left, result)
        result.append(root.val)
        inorder(root.right, result)
    return result

# BST build
root = None
for val in [5, 3, 7, 1, 4]:
    root = insert(root, val)

print('Inorder:', inorder(root, []))  # [1, 3, 4, 5, 7]
print('Search 4:', search(root, 4))  # True
print('Search 6:', search(root, 6))  # False
